// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint8 n, uint256 seed) public {
        // keep recipient count non-empty and bounded so the loop always runs
        n = uint8(bound(n, 1, 16));

        address[] memory tos = new address[](n);
        uint[] memory vs = new uint[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            // keep amount within the mul_uint256 safe domain
            vs[i] = bound(uint256(keccak256(abi.encode(seed, i, 0x7))), 0, type(uint256).max / 1000000000000000000);
        }

        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = c.transfer(tos, vs);

        // General rule: a completed transfer() call always signals success (returns true)
        assertTrue(ok);
    }
}
